// Two entry shapes in, one envelope out. Everything downstream reads this shape
// and nothing downstream knows which trigger fired.
const FALLBACK_UNIT = 'unknown';

// Subjects/bodies matching these never reach the model — see Privileged-Content Gate.
const PRIVILEGE_PATTERNS = [
  /\blitigation\b/i, /\bprivileged\b/i, /attorney[- ]client/i,
  /\bsubpoena\b/i, /\bwhistleblow/i, /internal investigation/i,
  /\bregulator(y)? (inquiry|request|notice)\b/i, /\bdata breach\b/i,
];

const out = [];

for (const item of $input.all()) {
  const j = item.json;
  let envelope;

  if (j.headers || j.body) {
    // Webhook form submission.
    const b = j.body || j;
    envelope = {
      source: 'form',
      source_message_id: String(b.submission_id || `form-${b.requester_email}-${b.needed_by || 'na'}`),
      requester_email: String(b.requester_email || '').trim().toLowerCase(),
      business_unit_claimed: b.business_unit || null,
      request_type_hint: b.request_type_hint || null,
      subject: b.summary || '(no summary)',
      body_text: String(b.detail || b.summary || ''),
      counterparty: b.counterparty || null,
      claimed_value_usd: Number.isFinite(Number(b.claimed_value_usd)) ? Number(b.claimed_value_usd) : null,
      needed_by: b.needed_by || null,
      has_attachment: Boolean(b.attachment_url),
    };
  } else {
    // Gmail message.
    const headers = j.payload?.headers || [];
    const header = (name) => (headers.find((h) => h.name.toLowerCase() === name) || {}).value || '';
    const from = header('from');
    const emailMatch = from.match(/<([^>]+)>/);
    envelope = {
      source: 'email',
      source_message_id: String(j.id),
      requester_email: (emailMatch ? emailMatch[1] : from).trim().toLowerCase(),
      business_unit_claimed: null,
      request_type_hint: null,
      subject: header('subject') || '(no subject)',
      body_text: String(j.snippet || ''),
      counterparty: null,
      claimed_value_usd: null,
      needed_by: null,
      has_attachment: Boolean(j.payload?.parts?.some((p) => p.filename)),
    };
  }

  // Hard cap on what can ever leave this workflow. A forwarded 40-message thread
  // is the common way privileged content reaches an API call by accident.
  envelope.body_text = envelope.body_text.slice(0, 4000);
  envelope.business_unit = envelope.business_unit_claimed || FALLBACK_UNIT;
  envelope.received_at = new Date().toISOString();
  envelope.privilege_hit = PRIVILEGE_PATTERNS.some(
    (re) => re.test(envelope.subject) || re.test(envelope.body_text),
  );

  if (!envelope.requester_email) {
    // No requester means no one to answer. Route it to a human rather than guess.
    envelope.privilege_hit = true;
    envelope.privilege_reason = 'no_requester_identified';
  }

  out.push({ json: envelope });
}

return out;

// Joins the directory row back onto the envelope. The envelope is the
// authority on what was asked; the directory is the authority on who asked.
const envelope = $('Normalize Request').first().json;
const row = $input.first()?.json || {};
const found = Boolean(row.business_unit);

return [{
  json: {
    ...envelope,
    business_unit: row.business_unit || envelope.business_unit_claimed || 'unknown',
    region: row.region || null,
    // 'unknown' is not the same as 'standard'. An unrecognised requester never
    // gets a self-serve answer, because we cannot tell whose paper they are on.
    risk_posture: found ? row.risk_posture : 'unknown',
    default_assignee: row.default_assignee || null,
    requester_known: found,
  },
}];

// The safety belt. Claude proposes; this node disposes. Every override is
// stamped onto the log row so you can measure how often each guard fires and
// retire the ones that never do.
const ctx = $('Merge Requester Context').first().json;
const raw = $input.first().json;

const WALK_AWAY_FLAGS = [
  'litigation', 'regulator', 'employment_termination',
  'm_and_a', 'data_breach', 'public_sector_counterparty',
];
const CONFIDENCE_FLOOR = 0.75;     // below this, no self-serve answer goes out
const VALUE_ESCALATION_USD = 250000; // claimed annual value that forces a lawyer

const SLA_BY_LANE = {
  self_serve: null,
  playbook: 16,
  lawyer: 40,
  awaiting_requester: 8,
  gc_escalation: 8,
};

function parseModel(payload) {
  // The model is asked for bare JSON, but markdown fences are the classic
  // regression after any prompt edit. Strip them, then parse.
  const text = payload?.content?.[0]?.text;
  if (typeof text !== 'string') throw new Error('no text block in response');
  const cleaned = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const parsed = JSON.parse(cleaned);
  if (!parsed.lane || !parsed.request_type) throw new Error('missing lane or request_type');
  return parsed;
}

let model;
let lane;
let overrideReason = null;

try {
  model = parseModel(raw);
  lane = model.lane;
} catch (err) {
  // Never fail open. An unparseable classification is a lawyer-lane request.
  return [{
    json: {
      ...ctx,
      request_type: 'other',
      model_lane: null,
      lane: 'gc_escalation',
      override_reason: 'parser_error: ' + err.message,
      confidence: 0,
      risk_flags: ['parser_error'],
      missing_fields: [],
      rationale: 'Classification could not be parsed. Routed to a human unread.',
      sla_business_hours: SLA_BY_LANE.gc_escalation,
      assignee: null,
    },
  }];
}

const flags = Array.isArray(model.risk_flags) ? model.risk_flags : [];
const missing = Array.isArray(model.missing_fields) ? model.missing_fields : [];
const confidence = Number(model.confidence);
const safeConfidence = Number.isFinite(confidence) ? confidence : 0;

// Overrides in priority order. First match wins and stops.
if (flags.some((f) => WALK_AWAY_FLAGS.includes(f))) {
  lane = 'gc_escalation';
  overrideReason = 'walk_away_flag:' + flags.filter((f) => WALK_AWAY_FLAGS.includes(f)).join('|');
} else if (Number(ctx.claimed_value_usd) >= VALUE_ESCALATION_USD) {
  lane = 'lawyer';
  overrideReason = 'claimed_value_over_' + VALUE_ESCALATION_USD;
} else if (lane === 'self_serve' && safeConfidence < CONFIDENCE_FLOOR) {
  lane = 'playbook';
  overrideReason = 'confidence_below_' + CONFIDENCE_FLOOR;
} else if (lane === 'self_serve' && ctx.risk_posture !== 'standard') {
  lane = 'playbook';
  overrideReason = 'risk_posture_' + ctx.risk_posture;
} else if (missing.length > 0 && lane !== 'lawyer') {
  lane = 'awaiting_requester';
  overrideReason = 'missing_fields:' + missing.join('|');
}

return [{
  json: {
    ...ctx,
    request_type: model.request_type,
    model_lane: model.lane,
    lane,
    override_reason: overrideReason,
    confidence: safeConfidence,
    risk_flags: flags,
    missing_fields: missing,
    rationale: String(model.rationale || '').slice(0, 300),
    sla_business_hours: SLA_BY_LANE[lane] ?? null,
    assignee: lane === 'self_serve' ? null : ctx.default_assignee,
  },
}];

