// Calendar hours are not business hours. Counting elapsed wall-clock time is
// the single most common reason an SLA alert fires at 3am on a Sunday for a
// request that is comfortably inside its window.
const BUSINESS_START = 9;   // local hour, inclusive
const BUSINESS_END = 18;    // local hour, exclusive
const HOURS_PER_DAY = BUSINESS_END - BUSINESS_START;
const TIERS = [
  { tier: 1, at: 0.5,  label: 'halfway' },
  { tier: 2, at: 1.0,  label: 'breached' },
  { tier: 3, at: 1.5,  label: 'badly overdue' },
];

function businessHoursBetween(startIso, end) {
  let cursor = new Date(startIso);
  let hours = 0;
  // Step an hour at a time. At the volumes this sweep sees (open requests, not
  // all requests) the loop is cheap and the arithmetic stays legible.
  while (cursor < end && hours < 2000) {
    const day = cursor.getUTCDay();
    const hour = cursor.getUTCHours();
    if (day >= 1 && day <= 5 && hour >= BUSINESS_START && hour < BUSINESS_END) hours += 1;
    cursor = new Date(cursor.getTime() + 3600 * 1000);
  }
  return hours;
}

const now = new Date();
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  if (!r.id) continue; // empty sweep

  const elapsed = businessHoursBetween(r.received_at, now);
  const ratio = elapsed / r.sla_business_hours;

  const due = TIERS.filter((t) => ratio >= t.at).pop();
  if (!due) continue;
  if (due.tier <= (r.last_escalated_tier || 0)) continue; // already shouted at this tier

  out.push({
    json: {
      ...r,
      elapsed_business_hours: elapsed,
      breach_tier: due.tier,
      breach_label: due.label,
      escalate_to: due.tier >= 3 ? '#legal-gc-escalations' : r.escalation_channel,
    },
  });
}

return out;

