// Turns the aggregate row into a report that states what to do about each
// number, not just what the number is. A dashboard nobody acts on is a cost.
const RECONTACT_CEILING = 0.15;   // above this, the self-serve templates are wrong
const OTHER_CEILING = 0.10;       // above this, the taxonomy is missing a type
const EMAIL_CEILING = 0.30;       // above this, the form has not landed

const d = $input.first().json;
const total = Number(d.total_requests) || 0;

if (!total) {
  return [{ json: { report: ':chart_with_upwards_trend: *Legal demand — last 7 days*\nNo requests logged. If that is a surprise, check the intake webhook and the legal-intake@ poll before assuming a quiet week.' } }];
}

const pct = (v) => Math.round((Number(v) / total) * 100);
const share = (v) => Number(v) / total;

const lines = [];
lines.push(':chart_with_upwards_trend: *Legal demand — last 7 days*');
lines.push(`*${total}* requests  |  self-serve ${pct(d.self_serve)}%  ·  playbook ${pct(d.playbook)}%  ·  lawyer ${pct(d.lawyer)}%  ·  GC ${pct(d.gc_escalation)}%  ·  awaiting requester ${pct(d.awaiting_requester)}%`);
lines.push(`Top types: ${d.top_request_types || 'n/a'}`);
lines.push(`Top business units: ${d.top_business_units || 'n/a'}`);
lines.push('');

const actions = [];

const recontactRate = Number(d.self_serve) ? Number(d.self_serve_recontacts) / Number(d.self_serve) : 0;
if (recontactRate > RECONTACT_CEILING) {
  actions.push(`:warning: ${Math.round(recontactRate * 100)}% of self-serve answers came back within 7 days (ceiling ${RECONTACT_CEILING * 100}%). The template is not answering the question — read five of them before touching the router.`);
}
if (share(d.type_other) > OTHER_CEILING) {
  actions.push(`:warning: ${pct(d.type_other)}% classified as "other" (ceiling ${OTHER_CEILING * 100}%). That is a missing request type in the taxonomy, not a model failure. Add it to the system prompt.`);
}
if (share(d.arrived_by_email) > EMAIL_CEILING) {
  actions.push(`:warning: ${pct(d.arrived_by_email)}% still arrived by email rather than the form (ceiling ${EMAIL_CEILING * 100}%). Channel discipline, not automation, is the gap.`);
}
if (share(d.unknown_requester) > 0.20) {
  actions.push(`:warning: ${pct(d.unknown_requester)}% of requesters were not in requester_directory, so none of them could be self-served. Whoever owns the directory has a backlog.`);
}
if (share(d.low_confidence) > 0.25) {
  actions.push(`:mag: ${pct(d.low_confidence)}% classified below 0.75 confidence. Sample ten and check whether the requests are genuinely ambiguous or the intake form is collecting too little.`);
}

lines.push(actions.length ? '*Needs a decision this week*' : ':white_check_mark: No threshold breached this week.');
lines.push(...actions);
lines.push('');
lines.push(`_Policy overrides fired on ${d.overridden} of ${total} requests. An override that fires on almost everything is a threshold to retune, not a rule that is working._`);

return [{ json: { report: lines.join('\n') } }];
